{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "In nonhuman primates, [18F]-(R)-TRACK, a close diethylacetamide heteroaryl analogue, crossed the BBB with high brain uptake, supporting CNS access for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "PET-CT in non-human primates showed initial high brain uptake and fast clearance for PBR102, a close analogue sharing the diethylacetamide side chain, confirming BBB penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Alpidem, a structurally related imidazopyridine acetamide, easily crossed the BBB in rat autoradiography with a BUI of 0.71% and a brain/plasma ratio of about 2.0-2.5.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Zolpidem, a closely related CNS-active acetamide, achieved central exposure after oral dosing in rats with measurable CSF and brain concentrations, demonstrating meaningful BBB penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "A pyrazolopyrimidine analogue crossed the BBB in mice and exhibited approximately 3 times the brain exposure relative to plasma, directly supporting CNS access for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "In baboon PET imaging, [11C]DMP696, a pyrazolopyrimidine analogue, distributed rapidly and uniformly throughout the brain, confirming BBB penetration.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a lipophilic, moderately sized pyrazolo[1,5-a]pyrimidine acetamide closely related to multiple CNS-penetrant drugs and radiotracers such as zolpidem, alpidem, and DPA-714 analogues. Direct in vivo evidence from these analogues consistently shows BBB permeability, brain uptake, and central exposure, so the query is predicted to have meaningful CNS access.",
  "evidence_gaps": [
    "No direct experimental measurement for the exact query molecule; prediction relies on close analogues with moderate Morgan similarity.",
    "Efflux transporter susceptibility and unbound brain concentrations were not directly assessed for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

